import os
import psycopg2
from flask import Flask, request, jsonify, g
import hashlib
import time

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, database=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def sanitize_order(order_val):
    """Allow only asc/desc for ORDER BY direction"""
    if order_val and order_val.lower() in ('asc', 'desc'):
        return order_val.lower()
    return 'asc'

def validate_api_key(key):
    """Timing-safe comparison for API key validation"""
    expected = os.environ.get('API_KEY', '')
    if len(key) != len(expected):
        return False
    result = 0
    for a, b in zip(key.encode(), expected.encode()):
        result |= a ^ b
    return result == 0

@app.before_request
def check_auth():
    api_key = request.headers.get('X-API-Key', '')
    if not validate_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/api/v2/reports/generate', methods=['POST'])
def generate_report():
    """Generate a filtered report based on user-specified criteria"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request'}), 400

    report_type = data.get('type', 'summary')
    filters = data.get('filters', {})
    group_by = data.get('group_by', 'department')
    order = sanitize_order(data.get('order'))

    # Build base query
    base_query = "SELECT employee_id, name, department, salary, hire_date FROM employees"
    conditions = []
    params = []

    # Apply safe parameterized filters
    if 'department' in filters:
        conditions.append("department = %s")
        params.append(filters['department'])
    if 'min_salary' in filters:
        conditions.append("salary >= %s")
        params.append(filters['min_salary'])
    if 'hired_after' in filters:
        conditions.append("hire_date >= %s")
        params.append(filters['hired_after'])

    if conditions:
        base_query += " WHERE " + " AND ".join(conditions)

    # Group by is user-controlled for report flexibility
    allowed_groups = ['department', 'hire_date', 'salary']
    if group_by not in allowed_groups:
        group_by = 'department'

    # Dynamic column selection for report type
    if report_type == 'detailed':
        # For detailed reports, allow custom column expressions
        custom_cols = data.get('columns', '')
        if custom_cols:
            base_query = f"SELECT {custom_cols} FROM employees"
            if conditions:
                base_query += " WHERE " + " AND ".join(conditions)

    base_query += f" ORDER BY {group_by} {order}"

    # Apply row limit
    limit = min(int(data.get('limit', 100)), 1000)
    base_query += f" LIMIT {limit}"

    try:
        db = get_db()
        cur = db.cursor()
        cur.execute(base_query, params)
        rows = cur.fetchall()
        columns = [desc[0] for desc in cur.description]
        results = [dict(zip(columns, row)) for row in rows]
        cur.close()
        return jsonify({'data': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/reports/templates', methods=['GET'])
def list_templates():
    """List available report templates"""
    templates = [
        {'id': 1, 'name': 'Salary Summary', 'type': 'summary'},
        {'id': 2, 'name': 'Department Detail', 'type': 'detailed'},
        {'id': 3, 'name': 'Hiring Trends', 'type': 'summary'}
    ]
    return jsonify({'templates': templates})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
